typedef int (*MathOp)(int, int);

int add(int a, int b) { return a + b; }
int subtract(int a, int b) { return a - b; }

MathOp op_ptr = add;
int result = op_ptr(10, 5); // Invocation

// Assignment safety
MathOp safe_op = (MathOp)subtract; // Explicit cast (C style)

void caller(MathOp cb, int x, int y) {
    if (cb) {
        cb(x, y);
    }
}
